/**
 * Private Chat V2 API Tests
 */

import { SynapseEnhancedClient } from "../index.ts";
import { loadTestConfig } from "./config.ts";
import { logger } from "../../logger.ts";

const log = logger.getChild("enhanced:test:private-chat-api");

interface TestResult {
    name: string;
    passed: boolean;
    responseTime: number;
    error?: string;
    response?: any;
}

export class PrivateChatApiTests {
    private client: SynapseEnhancedClient;
    private config: ReturnType<typeof loadTestConfig>;
    private createdSessionId: string | null = null;
    private creatorId?: string;

    public constructor() {
        this.config = loadTestConfig();
        this.client = new SynapseEnhancedClient({
            baseUrl: this.config.server.baseUrl,
            accessToken: this.config.server.accessToken,
            apiPrefix: this.config.server.apiPrefix,
            timeout: this.config.test.timeout,
        });
    }

    public async runAllTests(): Promise<TestResult[]> {
        log.info("");
        log.info("=============================");
        log.info("Running Private Chat V2 API Tests...");
        log.info("=============================");

        const results: TestResult[] = [];

        // Sequential tests as they depend on each other (create -> message -> close)

        // 1. Create Session
        results.push(await this.testCreateSession());

        // 2. Get Sessions
        if (this.createdSessionId) {
            results.push(await this.testGetSessions());

            // 3. Send Message
            results.push(await this.testSendMessage());

            // 4. Get Messages
            results.push(await this.testGetMessages());

            // 5. Get Unread Count
            results.push(await this.testGetUnreadCount());

            // 6. Close Session (cleanup)
            results.push(await this.testCloseSession());
        } else {
            log.warn("Skipping dependent tests due to session creation failure");
        }

        this.printResults(results);
        return results;
    }

    private printResults(results: TestResult[]): void {
        for (const result of results) {
            const icon = result.passed ? "✓" : "✗";
            log.info(`${icon} ${result.name}: ${result.passed ? "PASSED" : "FAILED"} (${result.responseTime}ms)`);
            if (result.error) {
                log.error(`  Error: ${result.error}`);
            }
        }
        const passed = results.filter((r) => r.passed).length;
        log.info("");
        log.info(`Private Chat API Results: ${passed}/${results.length} passed`);
    }

    private async testCreateSession(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const creatorId = `@testuser:${new URL(this.config.server.baseUrl).hostname}`;
            const otherUserId = `@targetuser:${new URL(this.config.server.baseUrl).hostname}`;

            const sessionId = await this.client.privateChat.createSession({
                creator_id: creatorId,
                participants: [otherUserId],
            });

            this.createdSessionId = sessionId;
            this.creatorId = creatorId;

            return {
                name: "Create Session",
                passed: !!sessionId,
                responseTime: Date.now() - startTime,
                response: { sessionId },
            };
        } catch (error: any) {
            return {
                name: "Create Session",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetSessions(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const sessions = await this.client.privateChat.getSessions();
            const found = sessions.some((s) => s.session_id === this.createdSessionId);

            return {
                name: "Get Sessions",
                passed: Array.isArray(sessions) && found,
                responseTime: Date.now() - startTime,
                response: { count: sessions.length },
            };
        } catch (error: any) {
            return {
                name: "Get Sessions",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testSendMessage(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            if (!this.createdSessionId) throw new Error("No session ID");

            const messageId = await this.client.privateChat.sendMessage({
                room_id: this.createdSessionId,
                content: "Hello from SDK Test",
                type: "m.text",
            });

            return {
                name: "Send Message",
                passed: !!messageId,
                responseTime: Date.now() - startTime,
                response: { messageId },
            };
        } catch (error: any) {
            return {
                name: "Send Message",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetMessages(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            if (!this.createdSessionId) throw new Error("No session ID");

            const messages = await this.client.privateChat.getMessages(this.createdSessionId, { limit: 10 });

            return {
                name: "Get Messages",
                passed: Array.isArray(messages) && messages.length > 0,
                responseTime: Date.now() - startTime,
                response: { count: messages.length },
            };
        } catch (error: any) {
            return {
                name: "Get Messages",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetUnreadCount(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const count = await this.client.privateChat.getUnreadCount();

            return {
                name: "Get Unread Count",
                passed: typeof count === "number",
                responseTime: Date.now() - startTime,
                response: { count },
            };
        } catch (error: any) {
            return {
                name: "Get Unread Count",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testCloseSession(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            if (!this.createdSessionId || !this.creatorId) throw new Error("No session ID or Creator ID");

            const result = await this.client.privateChat.closeSession(this.createdSessionId, this.creatorId);

            return {
                name: "Close Session",
                passed: result === true,
                responseTime: Date.now() - startTime,
                response: { result },
            };
        } catch (error: any) {
            return {
                name: "Close Session",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }
}

// Execute directly
const tests = new PrivateChatApiTests();
tests.runAllTests().catch((error) => log.error(error));
